// src/queries.js
const mysql = require('mysql2/promise');
const config = require('./config');

// Create connection pool
const pool = mysql.createPool({
  host: config.db.host,
  user: config.db.user,
  password: config.db.password,
  database: config.db.name,
  port: config.db.port,
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

/**
 * Execute a query with timing and logging
 * @param {string} sql - SQL query string
 * @param {Array} params - Query parameters
 * @returns {Object} Query result with timing information
 */
async function executeQuery(sql, params = []) {
  const startTime = Date.now();

  try {
    const [results, fields] = await pool.execute(sql, params);
    const duration = Date.now() - startTime;

    console.log(`Query executed in ${duration}ms: ${sql}`);

    return {
      results,
      fields,
      duration,
      success: true
    };
  } catch (error) {
    const duration = Date.now() - startTime;
    console.error(`Query failed after ${duration}ms: ${sql}`, error);
    throw error;
  }
}

/**
 * Get a user by their ID
 * @param {number} id - User ID
 * @returns {Object} User data or null if not found
 */
async function getUserById(id) {
  const sql = `SELECT id, name, email, created_at FROM users WHERE id = ?`;
  const result = await executeQuery(sql, [id]);
  return result.results[0] || null;
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of results to return
 * @param {number} offset - Number of results to skip
 * @returns {Array} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  // Ensure limit and offset are integers to prevent SQL injection
  const safeLimit = Math.max(1, Math.min(parseInt(limit) || 10, 100));
  const safeOffset = Math.max(0, parseInt(offset) || 0);

  const sql = `SELECT id, name, email, created_at FROM users ORDER BY id LIMIT ? OFFSET ?`;
  const result = await executeQuery(sql, [safeLimit, safeOffset]);
  return result.results;
}

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @param {number} limit - Maximum number of results
 * @returns {Array} Array of matching user objects
 */
async function searchUsers(query, limit = 10) {
  if (!query || query.trim().length === 0) {
    return [];
  }

  // Ensure limit is safe
  const safeLimit = Math.max(1, Math.min(parseInt(limit) || 10, 100));

  // Use parameterized query with LIKE and proper escaping
  // The database driver handles the escaping, but we also sanitize wildcards
  const safeQuery = `%${query.trim().replace(/[%_]/g, '')}%`;

  const sql = `SELECT id, name, email, created_at FROM users WHERE name LIKE ? OR email LIKE ? ORDER BY id LIMIT ?`;
  const result = await executeQuery(sql, [safeQuery, safeQuery, safeLimit]);
  return result.results;
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for graceful shutdown if needed
  pool
};

