const mysql = require('mysql2/promise');
const { performance } = require('perf_hooks');

// Create connection pool
const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'app_db',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

/**
 * Get user by ID
 * @param {number} id - User ID
 * @returns {Object|null} User object or null if not found
 */
async function getUserById(id) {
  const start = performance.now();

  try {
    // Validate input
    const userId = parseInt(id, 10);
    if (isNaN(userId) || userId <= 0) {
      throw new Error('Invalid user ID');
    }

    const [rows] = await pool.execute(
      'SELECT id, name, email, created_at FROM users WHERE id = ?',
      [userId]
    );

    const duration = performance.now() - start;
    console.log(`Query getUserById(${id}) took ${duration.toFixed(2)}ms`);

    return rows[0] || null;
  } catch (error) {
    const duration = performance.now() - start;
    console.error(`Query getUserById(${id}) failed after ${duration.toFixed(2)}ms:`, error.message);
    throw error;
  }
}

/**
 * Get all users with pagination
 * @param {number} limit - Maximum number of users to return
 * @param {number} offset - Number of users to skip
 * @returns {Array} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  const start = performance.now();

  try {
    // Validate and sanitize inputs
    const queryLimit = Math.min(Math.max(parseInt(limit, 10) || 10, 1), 100);
    const queryOffset = Math.max(parseInt(offset, 10) || 0, 0);

    const [rows] = await pool.execute(
      'SELECT id, name, email, created_at FROM users LIMIT ? OFFSET ?',
      [queryLimit, queryOffset]
    );

    const duration = performance.now() - start;
    console.log(`Query getAllUsers(limit=${limit}, offset=${offset}) took ${duration.toFixed(2)}ms`);

    return rows;
  } catch (error) {
    const duration = performance.now() - start;
    console.error(`Query getAllUsers(limit=${limit}, offset=${offset}) failed after ${duration.toFixed(2)}ms:`, error.message);
    throw error;
  }
}

/**
 * Search users by query string
 * @param {string} searchQuery - Search term for name or email
 * @returns {Array} Array of user objects matching the search
 */
async function searchUsers(searchQuery) {
  const start = performance.now();

  try {
    // Validate and sanitize input
    if (!searchQuery || typeof searchQuery !== 'string') {
      throw new Error('Search query is required and must be a string');
    }

    // Trim and escape special SQL characters
    const sanitizedQuery = `%${searchQuery.trim()}%`;

    const [rows] = await pool.execute(
      'SELECT id, name, email, created_at FROM users WHERE name LIKE ? OR email LIKE ?',
      [sanitizedQuery, sanitizedQuery]
    );

    const duration = performance.now() - start;
    console.log(`Query searchUsers("${searchQuery}") took ${duration.toFixed(2)}ms`);

    return rows;
  } catch (error) {
    const duration = performance.now() - start;
    console.error(`Query searchUsers("${searchQuery}") failed after ${duration.toFixed(2)}ms:`, error.message);
    throw error;
  }
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for testing or direct access if needed
  pool
};

const express = require('express');
const app = express();
