});

// PUT /users/:id - Update a user
app.put('/users/:id', (req, res) => {
  // This endpoint would also be updated to use database operations
  res.status(501).json({ error: 'Not implemented' });
});

// DELETE /users/:id - Delete a user
app.delete('/users/:id', (req, res) => {
  // This endpoint would also be updated to use database operations
  res.status(501).json({ error: 'Not implemented' });
});

app.listen(port, () => {
  console.log(`Server running at http://localhost:${port}`);
});

// Graceful shutdown
process.on('SIGINT', async () => {
  console.log('\nShutting down gracefully...');
  await db.pool.end();
  process.exit(0);
});

const mysql = require('mysql2');

// Create a connection (not a pool) for initialization
const connection = mysql.createConnection({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || ''
});

// Database and table setup
const setupDatabase = () => {
  // Create database if it doesn't exist
  connection.query(
    `CREATE DATABASE IF NOT EXISTS ${process.env.DB_NAME || 'app_db'}`,
    (err) => {
      if (err) {
        console.error('Error creating database:', err);
        return;
      }

      console.log('Database created or already exists');

      // Switch to the database
      connection.changeUser(
        { database: process.env.DB_NAME || 'app_db' },
        (err) => {
          if (err) {
            console.error('Error switching to database:', err);
            return;
          }

          // Create users table if it doesn't exist
          connection.query(
            `CREATE TABLE IF NOT EXISTS users (
              id INT AUTO_INCREMENT PRIMARY KEY,
              name VARCHAR(255) NOT NULL,
              email VARCHAR(255) NOT NULL UNIQUE,
              created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )`,
            (err) => {
              if (err) {
                console.error('Error creating users table:', err);
                return;
              }

              console.log('Users table created or already exists');

              // Add some sample data if the table is empty
              connection.query('SELECT COUNT(*) as count FROM users', (err, results) => {
                if (err || results[0].count > 0) {
                  console.log('Database setup complete');
                  connection.end();
                  return;
                }

                // Insert sample users
                const sampleUsers = [
                  ['John Doe', 'john@example.com'],
                  ['Jane Smith', 'jane@example.com'],
                  ['Bob Johnson', 'bob@example.com']
                ];

                connection.query(
                  'INSERT INTO users (name, email) VALUES ?',
                  [sampleUsers],
                  (err) => {
                    if (err) {
                      console.error('Error inserting sample data:', err);
                    } else {
                      console.log('Sample data inserted');
                    }

                    console.log('Database setup complete');
                    connection.end();
                  }
                );
              });
            }
          );
        }
      );
    }
  );
};

// Run the setup
setupDatabase();

// Handle connection errors
connection.on('error', (err) => {
  console.error('Database connection error:', err);
  if (err.code !== 'PROTOCOL_CONNECTION_LOST') {
    connection.end();
  }
});

