const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'myapp',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

// Utility to log query execution time
const timedQuery = async (sql, params) => {
  const start = Date.now();
  try {
    const [results, fields] = await pool.execute(sql, params);
    const duration = Date.now() - start;
    console.log(`Query executed in ${duration}ms: ${sql}`);
    return results;
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`Query failed after ${duration}ms: ${sql}`, error);
    throw error;
  }
};

// Query to get a user by ID
const getUserById = async (id) => {
  const sql = 'SELECT id, name, email FROM users WHERE id = ?';
  const results = await timedQuery(sql, [id]);
  return results[0] || null;
};

// Query to get all users with pagination
const getAllUsers = async (limit = 10, offset = 0) => {
  const sql = 'SELECT id, name, email FROM users LIMIT ? OFFSET ?';
  return await timedQuery(sql, [parseInt(limit), parseInt(offset)]);
};

// Query to search users by name or email
const searchUsers = async (query) => {
  const sanitizedQuery = `%${query.trim()}%`;
  const sql = 'SELECT id, name, email FROM users WHERE name LIKE ? OR email LIKE ?';
  return await timedQuery(sql, [sanitizedQuery, sanitizedQuery]);
};

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers
