const mysql = require('mysql2');

// Create a connection pool
const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'appdb',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

// Promisify the pool for async/await usage
const promisePool = pool.promise();

/**
 * Get a user by ID
 * @param {number} id - User ID
 * @returns {Promise<Object>} User object
 */
async function getUserById(id) {
  const startTime = Date.now();
  try {
    // Using parameterized query to prevent SQL injection
    const [rows] = await promisePool.execute(
      'SELECT id, name, email FROM users WHERE id = ? AND deleted = 0',
      [id]
    );

    if (rows.length === 0) {
      return null;
    }

    return rows[0];
  } finally {
    const duration = Date.now() - startTime;
    console.log(`getUserById query took ${duration}ms`);
  }
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users to return
 * @param {number} offset - Starting position
 * @returns {Promise<Array>} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  const startTime = Date.now();
  try {
    // Using parameterized query to prevent SQL injection
    const [rows] = await promisePool.execute(
      'SELECT id, name, email FROM users WHERE deleted = 0 ORDER BY id LIMIT ? OFFSET ?',
      [limit, offset]
    );

    return rows;
  } finally {
    const duration = Date.now() - startTime;
    console.log(`getAllUsers query took ${duration}ms`);
  }
}

/**
 * Search users by query string
 * @param {string} query - Search query for name or email
 * @returns {Promise<Array>} Array of matching user objects
 */
async function searchUsers(query) {
  const startTime = Date.now();
  try {
    // Using parameterized query with LIKE - escape special characters for safety
    // MySQL2 handles parameter escaping automatically
    const searchPattern = `%${query}%`;
    const [rows] = await promisePool.execute(
      'SELECT id, name, email FROM users WHERE deleted = 0 AND (name LIKE ? OR email LIKE ?) ORDER BY name',
      [searchPattern, searchPattern]
    );

    return rows;
  } finally {
    const duration = Date.now() - startTime;
    console.log(`searchUsers query took ${duration}ms`);
  }
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for graceful shutdown if needed
  pool
};

