// queries.js - Database query layer with connection pooling and logging

const mysql = require('mysql2');
const config = {
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'testdb',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0,
};

// Create connection pool
const pool = mysql.createPool(config).promise();

/**
 * Logs query execution time
 * @param {string} query - SQL query text
 * @param {number} startTime - Start timestamp
 */
const logQueryTiming = (query, startTime) => {
  const duration = Date.now() - startTime;
  console.log(`Query executed in ${duration}ms: ${query}`);
};

/**
 * Gets a user by ID with SQL injection prevention
 * @param {number} id - User ID
 * @returns {Object|null} User object or null if not found
 */
const getUserById = async (id) => {
  const startTime = Date.now();
  try {
    // Using parameterized query to prevent SQL injection
    const [rows] = await pool.execute(
      'SELECT id, name, email FROM users WHERE id = ?',
      [parseInt(id, 10)]
    );

    logQueryTiming('SELECT user by ID', startTime);
    return rows.length > 0 ? rows[0] : null;
  } catch (error) {
    logQueryTiming('Failed SELECT user by ID', startTime);
    console.error('Database query error:', error);
    throw error;
  }
};

/**
 * Gets all users with pagination
 * @param {number} limit - Maximum number of results
 * @param {number} offset - Number of results to skip
 * @returns {Array} Array of user objects
 */
const getAllUsers = async (limit = 10, offset = 0) => {
  const startTime = Date.now();
  try {
    // Using parameterized queries with LIMIT and OFFSET
    const [rows] = await pool.execute(
      'SELECT id, name, email FROM users LIMIT ? OFFSET ?',
      [parseInt(limit, 10), parseInt(offset, 10)]
    );

    logQueryTiming('SELECT all users with pagination', startTime);
    return rows;
  } catch (error) {
    logQueryTiming('Failed SELECT all users', startTime);
    console.error('Database query error:', error);
    throw error;
  }
};

/**
 * Searches users by name or email
 * @param {string} searchQuery - Search term
 * @param {number} limit - Maximum number of results
 * @param {number} offset - Number of results to skip
 * @returns {Array} Array of matching user objects
 */
const searchUsers = async (searchQuery, limit = 10, offset = 0) => {
  const startTime = Date.now();
  try {
    // Using parameterized query with LIKE and wildcards
    // The LIKE pattern is built with parameter binding to prevent SQL injection
    const [rows] = await pool.execute(
      `SELECT id, name, email 
       FROM users 
       WHERE name LIKE ? OR email LIKE ? 
       LIMIT ? OFFSET ?`,
      [`%${searchQuery}%`, `%${searchQuery}%`, parseInt(limit, 10), parseInt(offset, 10)]
    );

    logQueryTiming('User search query', startTime);
    return rows;
  } catch (error) {
    logQueryTiming('Failed user search query', startTime);
    console.error('Database query error:', error);
    throw error;
  }
};

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for connection management if needed
  pool,
};

