const { Pool } = require('pg');
const config = require('./config');

// Create connection pool
const pool = new Pool({
  connectionString: config.databaseUrl,
  max: 20, // maximum number of clients in the pool
  min: 2, // minimum number of clients in the pool
  idleTimeoutMillis: 30000, // how long a client is allowed to remain idle before being closed
  connectionTimeoutMillis: 2000, // how long to wait when connecting to the database
});

// Log pool errors
pool.on('error', (err) => {
  console.error('Unexpected error on idle client', err);
  // Reset the pool on error
  pool.end().then(() => {
    console.log('Pool has been ended due to error');
  });
});

/**
 * Executes a query with timing and error logging
 * @param {string} queryText - The SQL query text
 * @param {Array} params - Query parameters
 * @param {string} queryName - Name of the query for logging
 * @returns {Promise<Object>} Query result
 */
async function executeQuery(queryText, params = [], queryName = 'Unknown query') {
  const startTime = Date.now();

  try {
    const result = await pool.query(queryText, params);
    const duration = Date.now() - startTime;

    console.log(`${queryName} completed in ${duration}ms`);

    return result;
  } catch (error) {
    const duration = Date.now() - startTime;
    console.error(`${queryName} failed after ${duration}ms:`, error.message);
    throw error;
  }
}

/**
 * Get a user by their ID
 * @param {number} id - User ID
 * @returns {Promise<Object>} User object or null if not found
 */
async function getUserById(id) {
  const queryText = 'SELECT id, name, email FROM users WHERE id = $1';
  const params = [id];

  const result = await executeQuery(queryText, params, `Get user by ID: ${id}`);

  return result.rows[0] || null;
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users to return (default: 10)
 * @param {number} offset - Number of users to skip (default: 0)
 * @returns {Promise<Array>} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  // Input validation to prevent abuse of pagination parameters
  limit = Math.min(Math.max(parseInt(limit) || 10, 1), 100); // Limit between 1-100
  offset = Math.max(parseInt(offset) || 0, 0);

  const queryText = 'SELECT id, name, email FROM users ORDER BY id LIMIT $1 OFFSET $2';
  const params = [limit, offset];

  const result = await executeQuery(queryText, params, `Get all users (limit: ${limit}, offset: ${offset})`);

  return result.rows;
}

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @param {number} limit - Maximum number of results (default: 10)
 * @returns {Promise<Array>} Array of matching user objects
 */
async function searchUsers(query, limit = 10) {
  // Input validation
  if (!query || typeof query !== 'string') {
    throw new Error('Search query must be a non-empty string');
  }

  // Sanitize and prepare the search query
  // Using parameterized queries with ILIKE for case-insensitive search
  // The % wildcards are part of the parameter, not the SQL string
  const searchTerm = `%${query.trim()}%`;
  limit = Math.min(Math.max(parseInt(limit) || 10, 1), 100);

  const queryText = 'SELECT id, name, email FROM users WHERE name ILIKE $1 OR email ILIKE $1 ORDER BY id LIMIT $2';
  const params = [searchTerm, limit];

  const result = await executeQuery(queryText, params, `Search users: ${query}`);

  return result.rows;
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export pool for graceful shutdown
  pool,
};

