    );

    console.log(`Query getAllUsers(limit=${limit}, offset=${offset}) took ${Date.now() - startTime}ms`);
    return rows;
  } catch (error) {
    console.error(`Query getAllUsers(limit=${limit}, offset=${offset}) failed:`, error.message);
    throw error;
  }
}

/**
