  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'app_db',
  port: process.env.DB_PORT || 3306,
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

/**
 * Execute a query with timing and error logging
 * @param {string} sql - SQL query
 * @param {Array} params - Query parameters
 * @param {string} queryName - Name of the query for logging
 * @returns {Promise<Object>} Query result
 */
async function executeQuery(sql, params = [], queryName = 'Unknown query') {
  const start = performance.now();

  try {
    const [rows, fields] = await pool.execute(sql, params);
    const duration = performance.now() - start;

    console.log(`${queryName} completed in ${duration.toFixed(2)}ms`);

    return { rows, fields, duration };
  } catch (error) {
    const duration = performance.now() - start;
    console.error(`${queryName} failed after ${duration.toFixed(2)}ms:`, error.message);
    throw error;
  }
}

/**
 * Get a user by their ID
 * @param {number} id - User ID
 * @returns {Promise<Object>} User data or null if not found
 */
async function getUserById(id) {
  // Input validation to prevent SQL injection
  const userId = parseInt(id, 10);
  if (isNaN(userId) || userId <= 0) {
    throw new Error('Invalid user ID');
  }

  const result = await executeQuery(
    'SELECT id, name, email, created_at FROM users WHERE id = ? AND deleted_at IS NULL',
    [userId],
    'Get User By ID'
  );

  return result.rows[0] || null;
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users to return
 * @param {number} offset - Number of users to skip
 * @returns {Promise<Array>} Array of users
 */
async function getAllUsers(limit = 20, offset = 0) {
  // Input validation and sanitization
  const safeLimit = Math.min(Math.max(parseInt(limit, 10) || 20, 1), 100);
  const safeOffset = Math.max(parseInt(offset, 10) || 0, 0);

  const result = await executeQuery(
    'SELECT id, name, email, created_at FROM users WHERE deleted_at IS NULL ORDER BY created_at DESC LIMIT ? OFFSET ?',
    [safeLimit, safeOffset],
    'Get All Users'
  );

  return result.rows;
}

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @param {number} limit - Maximum number of results
 * @returns {Promise<Array>} Array of matching users
 */
async function searchUsers(query, limit = 20) {
  // Input validation and sanitization
  if (!query || typeof query !== 'string') {
    throw new Error('Search query is required and must be a string');
  }

  // Sanitize query - remove potentially harmful characters
  // We'll use a simple approach by escaping wildcards that could be abused
  const safeQuery = query.trim().replace(/[^a-zA-Z0-9\s@._-]/g, '');

  // Ensure we still have a valid query after sanitization
  if (safeQuery.length === 0) {
    throw new Error('Search query contains no valid characters');
  }

  // Add wildcards for partial matching
  const searchPattern = `%${safeQuery}%`;
  const safeLimit = Math.min(Math.max(parseInt(limit, 10) || 20, 1), 100);

  const result = await executeQuery(
    'SELECT id, name, email, created_at FROM users WHERE deleted_at IS NULL AND (name LIKE ? OR email LIKE ?) ORDER BY created_at DESC LIMIT ?',
    [searchPattern, searchPattern, safeLimit],
    'Search Users'
  );

  return result.rows;
}

