});

/**
 * Execute query with timing and logging
 * @param {string} query SQL query
 * @param {Array} params Query parameters
 * @returns {Promise} Query result
 */
async function executeQuery(query, params = []) {
  const start = Date.now();
  try {
    const [results] = await pool.execute(query, params);
    const duration = Date.now() - start;
    console.log(`Query executed in ${duration}ms: ${query}`);
    return results;
  } catch (error) {
    const duration = Date.now() - start;
    console.error(`Query failed after ${duration}ms: ${query}`, error);
    throw error;
  }
}

/**
 * Get user by ID with SQL injection prevention
 * @param {number} id User ID
 * @returns {Promise} User object or null
 */
async function getUserById(id) {
  if (typeof id !== 'number' || id <= 0 || !Number.isInteger(id)) {
    throw new Error('Invalid user ID');
  }

  const query = 'SELECT id, name, email FROM users WHERE id = ?';
  const results = await executeQuery(query, [id]);
  return results[0] || null;
}

/**
 * Get all users with pagination
 * @param {number} limit Maximum number of users
 * @param {number} offset Number of users to skip
 * @returns {Promise} Array of users
 */
async function getAllUsers(limit = 10, offset = 0) {
  // Input validation
  const validLimit = Math.max(1, Math.min(100, Number(limit) || 10));
  const validOffset = Math.max(0, Number(offset) || 0);

  const query = 'SELECT id, name, email FROM users LIMIT ? OFFSET ?';
  return executeQuery(query, [validLimit, validOffset]);
}

/**
 * Search users by name or email
 * @param {string} query Search term
 * @returns {Promise} Array of matching users
 */
async function searchUsers(searchQuery) {
  if (!searchQuery || typeof searchQuery !== 'string') {
    throw new Error('Search query must be a non-empty string');
  }

  // Sanitize and prepare search term for LIKE query
  const searchTerm = `%${searchQuery.trim().replace(/[%_]/g, '\$&')}%`;

  const query = `SELECT id, name, email FROM users WHERE name LIKE ? OR email LIKE ?`;
  return executeQuery(query, [searchTerm, searchTerm]);
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
