// queries.js - Database query functions with connection pooling and logging

const { Pool } = require('pg');
const logger = require('./logger'); // Assuming a simple logger module exists

// Connection pool configuration
const pool = new Pool({
  user: process.env.DB_USER || 'your_db_user',
  host: process.env.DB_HOST || 'localhost',
  database: process.env.DB_NAME || 'your_db_name',
  password: process.env.DB_PASSWORD || 'your_db_password',
  port: process.env.DB_PORT || 5432,
  max: 20, // Maximum number of clients in the pool
  idleTimeoutMillis: 30000, // Close idle clients after 30 seconds
  connectionTimeoutMillis: 2000, // Return an error after 2 seconds if connection could not be established
});

// Utility function to measure query execution time
const timedQuery = async (queryFn, queryName) => {
  const start = Date.now();
  try {
    const result = await queryFn();
    const duration = Date.now() - start;
    logger.info(`Query '${queryName}' executed successfully in ${duration}ms`);
    return result;
  } catch (error) {
    const duration = Date.now() - start;
    logger.error(`Query '${queryName}' failed after ${duration}ms: ${error.message}`);
    throw error;
  }
};

/**
 * Get a user by their ID
 * @param {number} id - The user ID
 * @returns {Promise<Object|null>} The user object or null if not found
 */
const getUserById = async (id) => {
  return timedQuery(async () => {
    const client = await pool.connect();
    try {
      const query = 'SELECT id, name, email FROM users WHERE id = $1';
      const { rows } = await client.query(query, [id]);
      return rows.length ? rows[0] : null;
    } finally {
      client.release();
    }
  }, 'getUserById');
};

/**
 * Get all users with pagination
 * @param {number} limit - Maximum number of users to return
 * @param {number} offset - Number of users to skip
 * @returns {Promise<Array>} Array of user objects
 */
const getAllUsers = async (limit = 10, offset = 0) => {
  return timedQuery(async () => {
    const client = await pool.connect();
    try {
      const query = 'SELECT id, name, email FROM users ORDER BY id LIMIT $1 OFFSET $2';
      const { rows } = await client.query(query, [limit, offset]);
      return rows;
    } finally {
      client.release();
    }
  }, 'getAllUsers');
};

/**
 * Search users by name or email
 * @param {string} query - Search term
 * @returns {Promise<Array>} Array of matching user objects
 */
const searchUsers = async (query) => {
  return timedQuery(async () => {
    const client = await pool.connect();
    try {
      // Use parameterized queries with LIKE and escape wildcards to prevent SQL injection
      const searchTerm = query.replace(/[%_]/g, '\$&'); // Escape % and _ characters
      const searchPattern = `%${searchTerm}%`;

      const selectQuery = `SELECT id, name, email FROM users 
                           WHERE name ILIKE $1 OR email ILIKE $1 
                           ORDER BY id`;
      const { rows } = await client.query(selectQuery, [searchPattern]);
      return rows;
    } finally {
      client.release();
    }
  }, 'searchUsers');
};

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
};

