// queries/queries.js
const mysql = require('mysql2');
const config = require('../config');

// Create a connection pool
const pool = mysql.createPool({
  host: config.db.host,
  user: config.db.user,
  password: config.db.password,
  database: config.db.database,
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

// Promise wrapper for the pool
const promisePool = pool.promise();

/**
 * Get a user by their ID.
 * @param {number} id - The user's ID.
 * @returns {Promise<Object>} The user object.
 */
async function getUserById(id) {
  const startTime = Date.now();
  try {
    const [rows] = await promisePool.execute(
      'SELECT id, name, email FROM users WHERE id = ?',
      [id]
    );
    const duration = Date.now() - startTime;
    console.log(`[QUERY] getUserById(${id}) executed in ${duration}ms`);

    if (rows.length === 0) {
      return null;
    }
    return rows[0];
  } catch (error) {
    const duration = Date.now() - startTime;
    console.error(`[QUERY] getUserById(${id}) failed after ${duration}ms:`, error.message);
    throw error;
  }
}

/**
 * Get all users with pagination.
 * @param {number} limit - Number of users to return.
 * @param {number} offset - Number of users to skip.
 * @returns {Promise<Array>} Array of user objects.
 */
async function getAllUsers(limit = 10, offset = 0) {
  const startTime = Date.now();
  try {
    const [rows] = await promisePool.execute(
      'SELECT id, name, email FROM users LIMIT ? OFFSET ?',
      [parseInt(limit), parseInt(offset)]
    );
    const duration = Date.now() - startTime;
    console.log(`[QUERY] getAllUsers(limit=${limit}, offset=${offset}) executed in ${duration}ms`);
    return rows;
  } catch (error) {
    const duration = Date.now() - startTime;
    console.error(`[QUERY] getAllUsers(limit=${limit}, offset=${offset}) failed after ${duration}ms:`, error.message);
    throw error;
  }
}

/**
 * Search users by name or email.
 * @param {string} query - Search term.
 * @returns {Promise<Array>} Array of user objects matching the search.
 */
async function searchUsers(query) {
  const startTime = Date.now();
  try {
    // Using parameterized query to prevent SQL injection
    const searchPattern = `%${query.trim()}%`;
    const [rows] = await promisePool.execute(
      `SELECT id, name, email 
       FROM users 
       WHERE name LIKE ? OR email LIKE ?`,
      [searchPattern, searchPattern]
    );
    const duration = Date.now() - startTime;
    console.log(`[QUERY] searchUsers(query='${query}') executed in ${duration}ms`);
    return rows;
  } catch (error) {
    const duration = Date.now() - startTime;
    console.error(`[QUERY] searchUsers(query='${query}') failed after ${duration}ms:`, error.message);
    throw error;
  }
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers
};

