// queries.js - Database query functions
const mysql = require('mysql2/promise');
const pool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  user: process.env.DB_USER || 'root',
  password: process.env.DB_PASSWORD || '',
  database: process.env.DB_NAME || 'appdb',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

/**
 * Get a single user by ID with SQL injection prevention
 * @param {number} id - User ID
 * @returns {Object} User object or null
 */
async function getUserById(id) {
  const startTime = Date.now();
  try {
    const [rows] = await pool.execute('SELECT id, name, email FROM users WHERE id = ?', [id]);
    return rows[0] || null;
  } finally {
    const duration = Date.now() - startTime;
    console.log(`getUserById(${id}) executed in ${duration}ms`);
  }
}

/**
 * Get all users with pagination
 * @param {number} limit - Number of users to return
 * @param {number} offset - Starting position
 * @returns {Array} Array of user objects
 */
async function getAllUsers(limit = 10, offset = 0) {
  const startTime = Date.now();
  try {
    const [rows] = await pool.execute(
      'SELECT id, name, email FROM users LIMIT ? OFFSET ?', 
      [limit, offset]
    );
    return rows;
  } finally {
    const duration = Date.now() - startTime;
    console.log(`getAllUsers(limit=${limit}, offset=${offset}) executed in ${duration}ms`);
  }
}

/**
 * Search users by name or email with wildcard matching
 * @param {string} query - Search term
 * @returns {Array} Array of matching user objects
 */
async function searchUsers(query) {
  const startTime = Date.now();
  try {
    // Use parameterized query with wildcards added in the parameter
    const searchParam = `%${query}%`;
    const [rows] = await pool.execute(
      'SELECT id, name, email FROM users WHERE name LIKE ? OR email LIKE ?', 
      [searchParam, searchParam]
    );
    return rows;
  } finally {
    const duration = Date.now() - startTime;
    console.log(`searchUsers("${query}") executed in ${duration}ms`);
  }
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers
};

